<?phpclass Session{	public function __construct()	{		self::init();	}	public static function init()	{		session_start();		session_write_close();	}	public static function set($key, $val)	{		session_start();		$_SESSION[$key] = $val;		session_write_close();	}	public static function get($key)	{		if (isset($_SESSION[$key])) {			return $_SESSION[$key];		} else {			return false;		}	}	public static function delete($key) {		if (isset($_SESSION[$key])) {			session_start();			unset($_SESSION[$key]);			session_write_close();			return true;		} else {			return false;		}	}	public static function checkSession(){		if (self::get('login') == true) {			if(self::get('lock')==true){				return 0;			}			return 1;		} else {			if(  strpos(basename($_SERVER['REQUEST_URI']), 'login') === false) {				$url = basename($_SERVER['REQUEST_URI'], '?' . (isset($_SERVER['QUERY_STRING']) ? '?' . $_SERVER['QUERY_STRING'] : ''));				self::set('REQUEST_URI', $url);			}			return -1;		}	}	public static function destroy()	{		session_start();		session_destroy();		unset($_SESSION);		session_write_close();	}	public function __destruct()	{		self::destroy();	}}